/**
 * Echo an icon safely.
 *
 * @param string $name Icon name.
 */
function cybertech_demo_icon( string $name ): void {
	$allowed = [
		'svg'    => [
			'xmlns'           => true,
			'width'           => true,
			'height'          => true,
			'viewbox'         => true,
			'fill'            => true,
			'stroke'          => true,
			'stroke-width'    => true,
			'stroke-linecap'  => true,
			'stroke-linejoin' => true,
			'aria-hidden'     => true,
			'focusable'       => true,
		],
		'path'   => [ 'd' => true, 'fill' => true, 'stroke' => true, 'stroke-width' => true ],
		'rect'   => [ 'x' => true, 'y' => true, 'width' => true, 'height' => true, 'rx' => true ],
		'circle' => [ 'cx' => true, 'cy' => true, 'r' => true, 'fill' => true, 'stroke' => true ],
	];
	echo wp_kses( cybertech_demo_icon_svg( $name ), $allowed );
}
